//! The conformance vectors in verify/vectors, generated by a reference
//! script from the specification's notation, with expected outcomes
//! written by hand. Every vector must reproduce its expected outcome field
//! for field; the files must match their digest file.

use anchorstamp_core::{SchemeTag, Strength};
use anchorstamp_verify::k::{Bundle, Quote};
use anchorstamp_verify::{
    Anchor, Cap, DeclaredPath, Detail, Health, Kind, Path, Unclaimed, Within, exec, s, test,
};
use p256::ecdsa::signature::Verifier as _;
use sha2::{Digest, Sha256};

const A: &str = include_str!("../../../verify/vectors/vectors-a.txt");
const B: &str = include_str!("../../../verify/vectors/vectors-b.txt");
const SIGS: &str = include_str!("../../../verify/vectors/signatures.txt");
const DIGESTS: &str = include_str!("../../../verify/vectors/vectors.sha256");

fn hex(s: &str) -> Vec<u8> {
    assert_eq!(s.len() % 2, 0, "odd hex");
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

/// One vector: its name and its lines, split at the first space.
struct Vector {
    name: String,
    lines: Vec<(String, String)>,
}

impl Vector {
    fn all(&self, key: &str) -> Vec<&str> {
        self.lines.iter().filter(|(k, _)| k == key).map(|(_, v)| v.as_str()).collect()
    }
    fn one(&self, key: &str) -> Option<&str> {
        let v = self.all(key);
        assert!(v.len() <= 1, "{}: {key} twice", self.name);
        v.first().copied()
    }
    fn expect(&self) -> Vec<(String, String)> {
        self.all("expect")
            .iter()
            .map(|e| {
                let (k, v) = e.split_once(' ').unwrap_or((e, ""));
                (k.to_string(), v.to_string())
            })
            .collect()
    }
}

fn vectors(text: &str) -> Vec<Vector> {
    let mut out = Vec::new();
    let mut cur: Option<Vector> = None;
    for line in text.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let (k, v) = line.split_once(' ').unwrap_or((line, ""));
        match k {
            "vector" => cur = Some(Vector { name: v.to_string(), lines: Vec::new() }),
            "end" => out.push(cur.take().expect("end without vector")),
            _ => cur.as_mut().expect("line outside a vector").lines.push((k.into(), v.into())),
        }
    }
    assert!(cur.is_none(), "unterminated vector");
    out
}

fn cap(name: &str) -> Cap {
    match name {
        "SelfProvAbsent" => Cap::SelfProvAbsent,
        "SelfProvUnappraised" => Cap::SelfProvUnappraised,
        "SequenceUnappraised" => Cap::SequenceUnappraised,
        "AnchorOperatorAsserted" => Cap::AnchorOperatorAsserted,
        "TransportOperatorAsserted" => Cap::TransportOperatorAsserted,
        "BootConfigUnappraised" => Cap::BootConfigUnappraised,
        "EkChainUnvalidated" => Cap::EkChainUnvalidated,
        "AkPinnedLocally" => Cap::AkPinnedLocally,
        "BootAsserted" => Cap::BootAsserted,
        "PathUnverified" => Cap::PathUnverified,
        "RootCanInsert" => Cap::RootCanInsert,
        "Interpreted" => Cap::Interpreted,
        "Unanchored" => Cap::Unanchored,
        other => panic!("unknown cap {other}"),
    }
}

fn detail(name: &str) -> Detail {
    match name {
        "SubjectMismatch" => Detail::SubjectMismatch,
        "Unobserved" => Detail::Unobserved,
        other => panic!("unknown detail {other}"),
    }
}

fn anchor(v: &str) -> Anchor {
    if v == "none" {
        return Anchor::None;
    }
    let f: Vec<(&str, u64)> = v
        .strip_prefix("within ")
        .expect("within")
        .split(' ')
        .map(|kv| {
            let (k, n) = kv.split_once('=').unwrap();
            (k, n.parse().unwrap())
        })
        .collect();
    let get = |k: &str| f.iter().find(|(n, _)| *n == k).unwrap().1;
    let u32_of = |k: &str| u32::try_from(get(k)).unwrap();
    Anchor::Within(Within {
        reset_count: u32_of("reset"),
        from: Some(get("from")),
        to: get("to"),
        restart_from: Some(u32_of("restart_from")),
        restart_to: u32_of("restart_to"),
        safe: get("safe") == 1,
    })
}

/// Compare the health fields an expectation names; the rest are not stated.
fn check_health(name: &str, got: &Health, want: &str) {
    for kv in want.split(' ') {
        let (k, n) = kv.split_once('=').unwrap();
        let n: u64 = n.parse().unwrap();
        let g = match k {
            "gaps" => got.gaps,
            "breaks" => got.breaks,
            "forks" => got.forks,
            "excluded" => got.excluded,
            "touches" => u64::from(got.touches_claim),
            "broken" => u64::from(got.evidence_broken),
            other => panic!("{name}: unknown health field {other}"),
        };
        assert_eq!(g, n, "{name}: health {k}: got {got:?}");
    }
}

fn unclaimed(v: &str) -> Vec<Unclaimed> {
    v.split(',')
        .map(|u| {
            let (i, n) = u.split_once(':').unwrap();
            Unclaimed { instance: hex(i).try_into().unwrap(), index: n.parse().unwrap() }
        })
        .collect()
}

fn claim(v: &Vector) -> Option<Vec<u8>> {
    match v.one("claim").expect("a claim line") {
        "local" => None,
        h => Some(hex(h)),
    }
}

/// The expected LINUX_EXEC outcome, assembled from the expect lines.
fn check_exec(v: &Vector, o: &anchorstamp_verify::Outcome) {
    let e = v.expect();
    let get = |k: &str| e.iter().find(|(n, _)| n == k).map(|(_, x)| x.as_str());
    let caps = || get("caps").unwrap().split(',').map(cap).collect::<Vec<_>>();
    let strength = || match get("strength").unwrap() {
        "100" => Strength::SOFTWARE,
        "400" => Strength::ATTESTED,
        other => panic!("strength {other}"),
    };
    let want = match get("kind").unwrap() {
        "Agrees" => {
            assert_eq!(get("scheme"), Some("0001"));
            Kind::Agrees {
                strength: strength(),
                scheme: SchemeTag::LINUX_EXEC,
                caps: caps(),
                also: get("also").unwrap().parse().unwrap(),
            }
        }
        "Disagrees" => Kind::Disagrees { detail: detail(get("detail").unwrap()), strength: strength(), caps: caps() },
        "NotCovered" => Kind::NotCovered {
            windows: get("windows")
                .unwrap()
                .split(',')
                .map(|w| {
                    let (lo, hi) = w.split_once('-').unwrap();
                    (lo.parse().unwrap(), if hi == "open" { None } else { Some(hi.parse().unwrap()) })
                })
                .collect(),
        },
        "NothingToCompare" => Kind::NothingToCompare,
        other => panic!("kind {other}"),
    };
    assert_eq!(o.kind, want, "{}: kind", v.name);
    assert_eq!(o.anchor, anchor(get("anchor").unwrap()), "{}: anchor", v.name);
    if let Some(h) = get("health") {
        check_health(&v.name, &o.health, h);
    }
}

fn k_bundle_run(v: &Vector) {
    let list = hex(v.one("list").unwrap());
    let ak = hex(v.one("ak").unwrap());
    let boot: [u8; 16] = hex(v.one("boot").unwrap()).try_into().unwrap();
    let nonce = hex(v.one("nonce").unwrap());
    let quotes_raw: Vec<(Vec<u8>, Vec<u8>, Vec<u8>)> = v
        .all("quote")
        .iter()
        .map(|q| {
            let p: Vec<&str> = q.split(' ').collect();
            (hex(p[0]), hex(p[1]), hex(p[2]))
        })
        .collect();
    let quotes: Vec<Quote> =
        quotes_raw.iter().map(|(a, s, p)| Quote { attest: a, signature: s, pcr7: p }).collect();
    let ev = anchorstamp_verify::k::build(&Bundle {
        list: &list,
        quotes: &quotes,
        ak_spki: &ak,
        boot_id: Some(boot),
        nonce: Some(&nonce),
        interval_s: v.one("interval").map(|i| i.parse().unwrap()),
    });
    let c = claim(v);
    if let Some(scope) = v.one("scope") {
        let scope: Vec<u32> = scope.split(',').map(|u| u.parse().unwrap()).collect();
        let claims: Vec<&[u8]> = c.iter().map(Vec::as_slice).collect();
        let want = v.expect().iter().find(|(k, _)| k == "unclaimed").map(|(_, x)| unclaimed(x)).unwrap();
        assert_eq!(exec::account(&claims, &ev, &scope), want, "{}: unclaimed", v.name);
        return;
    }
    check_exec(v, &exec::join(c.as_deref(), &ev, DeclaredPath::Direct));
}

fn s_run(v: &Vector) {
    let records: Vec<Vec<u8>> = v.all("record").iter().map(|r| hex(r)).collect();
    let refs: Vec<&[u8]> = records.iter().map(Vec::as_slice).collect();
    let ev = s::build(&refs);
    check_exec(v, &exec::join(claim(v).as_deref(), &ev, DeclaredPath::Direct));
}

#[test]
fn files_match_their_digests() {
    for (name, text) in [("vectors-a.txt", A), ("vectors-b.txt", B), ("signatures.txt", SIGS)] {
        let want = DIGESTS
            .lines()
            .find_map(|l| l.strip_suffix(&format!("  {name}")))
            .unwrap_or_else(|| panic!("{name} not in the digest file"));
        let got: String = Sha256::digest(text.as_bytes()).iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(got, want, "{name}");
    }
}

#[test]
fn every_index_axis_vector() {
    let vs = vectors(A);
    let names: Vec<&str> = vs.iter().map(|v| v.name.as_str()).collect();
    assert_eq!(
        names,
        ["v01", "v02", "v03", "v04", "v05", "v06", "v07", "v09", "v10", "v13", "v14", "v14b", "v11", "v15"]
    );
    for v in &vs {
        let records: Vec<Vec<u8>> = v.all("record").iter().map(|r| hex(r)).collect();
        let refs: Vec<&[u8]> = records.iter().map(Vec::as_slice).collect();
        let c = claim(v);
        let e = v.expect();
        let get = |k: &str| e.iter().find(|(n, _)| n == k).map(|(_, x)| x.as_str());
        if let Some(u) = get("unclaimed") {
            let claims: Vec<&[u8]> = c.iter().map(Vec::as_slice).collect();
            assert_eq!(test::account(&claims, &refs), unclaimed(u), "{}", v.name);
            continue;
        }
        let o = test::join(c.as_deref(), &refs, DeclaredPath::Relayed { hops: 1 });
        let want = match get("kind").unwrap() {
            "Agrees" => {
                assert_eq!(get("scheme"), Some("ffff"));
                assert_eq!(get("strength"), Some("100"));
                test::Kind::Agrees {
                    strength: Strength::SOFTWARE,
                    scheme: SchemeTag::TEST,
                    caps: get("caps").unwrap().split(',').map(cap).collect(),
                }
            }
            "Disagrees" => test::Kind::Disagrees { detail: detail(get("detail").unwrap()) },
            "NothingToCompare" => test::Kind::NothingToCompare,
            other => panic!("{}: kind {other}", v.name),
        };
        assert_eq!(o.kind, want, "{}: kind", v.name);
        check_health(&v.name, &o.health, get("health").unwrap());
        let path = match get("path").unwrap() {
            "NothingArrived" => Path::NothingArrived,
            "Relayed1" => Path::Relayed { hops: 1 },
            other => panic!("path {other}"),
        };
        assert_eq!(o.path, path, "{}: path", v.name);
        assert_eq!(o.anchor, anchor(get("anchor").unwrap()), "{}: anchor", v.name);
    }
}

#[test]
fn every_linux_exec_vector() {
    let vs = vectors(B);
    let mut names: Vec<String> = vs.iter().map(|v| v.name.clone()).collect();
    names.sort();
    let mut want: Vec<String> = (1..=38).map(|n| format!("w{n:02}")).collect();
    want.extend((1..=4).map(|n| format!("x{n:02}")));
    assert_eq!(names, want);
    for v in &vs {
        match v.one("profile") {
            Some("K") => k_bundle_run(v),
            Some("S") => s_run(v),
            other => panic!("{}: profile {other:?}", v.name),
        }
    }
}

#[test]
fn the_rfc6979_known_answer_verifies() {
    // RFC 6979 A.2.5: P-256, SHA-256, message "sample"; a published test
    // key, not a secret, anchoring nothing
    let mut spki = anchorstamp_verify::k::AK_SPKI_PREFIX.to_vec();
    spki.extend(hex(
        "0460FED4BA255A9D31C961EB74C6356D68C049B8923B61FA6CE669622E60F29FB67903FE1008B8BC99A41AE9E95628BC64F2F1B20C2D7E9F5177A3C294D4462299",
    ));
    let ak = anchorstamp_verify::k::parse_ak(&spki).expect("a point on the curve");
    let mut tpmt = vec![0x00, 0x18, 0x00, 0x0B, 0x00, 0x20];
    tpmt.extend(hex("EFD48B2AACB6A8FD1140DD9CD45E81D69D2C877B56AAF991C34D0EA84EAF3716"));
    tpmt.extend([0x00, 0x20]);
    tpmt.extend(hex("F7CB1C942D657C41D436C7A1B6E29F65F3E900DBB9AFF4064DC4AB2F843ACDA8"));
    let sig = anchorstamp_verify::k::parse_signature(&tpmt).expect("parses");
    assert!(ak.verify(b"sample", &sig).is_ok());
    assert!(ak.verify(b"samplf", &sig).is_err());
}

#[test]
fn the_high_s_and_short_scalar_vectors_are_what_they_say() {
    // w17: each quote's s is n - s of the same quote in w01
    let n = hex("FFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551");
    let all = vectors(B);
    let s_of = |name: &str| -> Vec<Vec<u8>> {
        let v = all.iter().find(|v| v.name == name).unwrap();
        v.all("quote").iter().map(|q| { let g = hex(q.split(' ').nth(1).unwrap()); g[g.len() - 32..].to_vec() }).collect()
    };
    for (a, b) in s_of("w01").iter().zip(s_of("w17")) {
        let mut bytes = [0u8; 32];
        let mut carry = 0u16;
        for i in (0..32).rev() {
            let t = u16::from(a[i]) + u16::from(b[i]) + carry;
            bytes[i] = u8::try_from(t % 256).unwrap();
            carry = t / 256;
        }
        assert_eq!(carry, 0);
        assert_eq!(bytes.to_vec(), n, "s + s' = n");
    }
    // x01 carries a scalar shorter than 32 bytes
    let x01 = all.iter().find(|v| v.name == "x01").unwrap();
    assert!(x01.all("quote").iter().any(|q| hex(q.split(' ').nth(1).unwrap()).len() < 72));
}
